def web_search_exa(query, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0380000" if __import__("os").path.isdir("./environment_mix/0380000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    operations = _load("operations.json")

    def _oplog(workspace_id, api_key_id, typ, status, request_obj, result_obj=None, error_obj=None, cost_units=0, started_at=None, finished_at=None, webset_id=None):
        op_id = "op_" + hashlib.sha256((now + "|" + typ + "|" + (workspace_id or "") + "|" + str(len(operations)+1)).encode("utf-8")).hexdigest()[:24]
        row = {
            "id": op_id,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "type": typ,
            "webset_id": webset_id,
            "status": status,
            "request": request_obj if request_obj is not None else {},
            "result": result_obj,
            "error": error_obj,
            "cost_units": int(cost_units) if isinstance(cost_units, int) and cost_units >= 0 else 0,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(row)
        _save("operations.json", operations)
        return row

    def _month_key(dt_iso_z):
        try:
            d = datetime.datetime.fromisoformat(dt_iso_z.replace("Z", "+00:00"))
        except Exception:
            d = datetime.datetime.utcnow()
        return (d.year, d.month)

    def _sum_cost(workspace_id, typ, year, month):
        s = 0
        for op in operations:
            if op.get("workspace_id") != workspace_id: 
                continue
            if op.get("type") != typ:
                continue
            ca = op.get("created_at") or op.get("started_at") or op.get("updated_at")
            if not isinstance(ca, str):
                continue
            try:
                d = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00"))
            except Exception:
                continue
            if d.year == year and d.month == month:
                cu = op.get("cost_units")
                if isinstance(cu, int) and cu >= 0:
                    s += cu
        return s

    # Validate inputs
    if not isinstance(query, str) or not query.strip():
        # attempt to attribute to some workspace even for validation errors? spec doesn't require, but business rule says all tool calls must be attributable
        # We'll choose an active workspace with an active key if possible; else any active workspace; else any workspace.
        ws_row = None
        key_row = None
        for k in api_keys:
            if k.get("status") == "active":
                ws = next((w for w in workspaces if w.get("id") == k.get("workspace_id")), None)
                if ws:
                    ws_row, key_row = ws, k
                    break
        if ws_row is None:
            ws_row = next((w for w in workspaces if w.get("status") == "active"), None) or (workspaces[0] if workspaces else None)
        op = _oplog(ws_row["id"] if ws_row else "ws_unknown", key_row["id"] if key_row else None,
                    "exa_web_search", "failed",
                    {"query": query, "limit": limit, "cursor": cursor},
                    result_obj=None,
                    error_obj={"code": "VALIDATION_ERROR", "message": "query is required and must be a non-empty string"},
                    cost_units=0,
                    started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "query is required and must be a non-empty string", operation_id=op["id"])

    if limit is not None and (not isinstance(limit, int) or limit <= 0):
        ws_row = None
        key_row = None
        for k in api_keys:
            if k.get("status") == "active":
                ws = next((w for w in workspaces if w.get("id") == k.get("workspace_id")), None)
                if ws:
                    ws_row, key_row = ws, k
                    break
        if ws_row is None:
            ws_row = next((w for w in workspaces if w.get("status") == "active"), None) or (workspaces[0] if workspaces else None)
        op = _oplog(ws_row["id"] if ws_row else "ws_unknown", key_row["id"] if key_row else None,
                    "exa_web_search", "failed",
                    {"query": query, "limit": limit, "cursor": cursor},
                    error_obj={"code": "VALIDATION_ERROR", "message": "limit must be a positive integer"},
                    cost_units=0, started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "limit must be a positive integer", operation_id=op["id"])

    # Cursor handling: opaque but must be parseable if provided
    start_offset = 0
    cursor_query = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            ws_row = next((w for w in workspaces if w.get("status") == "active"), None) or (workspaces[0] if workspaces else None)
            op = _oplog(ws_row["id"] if ws_row else "ws_unknown", None,
                        "exa_web_search", "failed",
                        {"query": query, "limit": limit, "cursor": cursor},
                        error_obj={"code": "VALIDATION_ERROR", "message": "cursor is malformed"},
                        cost_units=0, started_at=now, finished_at=now)
            return _err("VALIDATION_ERROR", "cursor is malformed", operation_id=op["id"])
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or "o" not in payload or "q" not in payload:
                raise ValueError("bad cursor payload")
            if not isinstance(payload["o"], int) or payload["o"] < 0:
                raise ValueError("bad offset")
            if not isinstance(payload["q"], str):
                raise ValueError("bad query")
            start_offset = payload["o"]
            cursor_query = payload["q"]
        except Exception:
            ws_row = next((w for w in workspaces if w.get("status") == "active"), None) or (workspaces[0] if workspaces else None)
            op = _oplog(ws_row["id"] if ws_row else "ws_unknown", None,
                        "exa_web_search", "failed",
                        {"query": query, "limit": limit, "cursor": cursor},
                        error_obj={"code": "VALIDATION_ERROR", "message": "cursor is malformed"},
                        cost_units=0, started_at=now, finished_at=now)
            return _err("VALIDATION_ERROR", "cursor is malformed", operation_id=op["id"])

        if cursor_query != query:
            ws_row = next((w for w in workspaces if w.get("status") == "active"), None) or (workspaces[0] if workspaces else None)
            op = _oplog(ws_row["id"] if ws_row else "ws_unknown", None,
                        "exa_web_search", "failed",
                        {"query": query, "limit": limit, "cursor": cursor},
                        error_obj={"code": "VALIDATION_ERROR", "message": "cursor does not match query"},
                        cost_units=0, started_at=now, finished_at=now)
            return _err("VALIDATION_ERROR", "cursor does not match query", operation_id=op["id"])

    # Ambient auth resolution: pick any working (active workspace + active api_key) combination, else UNAUTHORIZED
    ws = None
    key = None
    for k in api_keys:
        if k.get("status") != "active":
            continue
        w = next((x for x in workspaces if x.get("id") == k.get("workspace_id")), None)
        if w and w.get("status") in ("active", "suspended", "deleted"):
            ws = w
            key = k
            break
    if ws is None:
        # no way to attribute to a real workspace for this call
        return _err("UNAUTHORIZED", "No valid workspace credentials available")

    # Quota enforcement for searches
    year, month = _month_key(now)
    used = _sum_cost(ws["id"], "exa_web_search", year, month)
    lim = ws.get("monthly_search_limit")
    if not isinstance(lim, int) or lim < 0:
        lim = 0

    req_obj = {"query": query, "limit": limit, "cursor": cursor}
    started_at = now

    if used + 1 > lim:
        op = _oplog(ws["id"], key["id"], "exa_web_search", "failed", req_obj,
                    result_obj=None,
                    error_obj={"code": "QUOTA_EXCEEDED", "message": "Monthly search quota exceeded", "used": used, "limit": lim},
                    cost_units=0,
                    started_at=started_at, finished_at=now)
        return _err("QUOTA_EXCEEDED", "Monthly search quota exceeded", used=used, limit=lim, operation_id=op["id"])

    # Simulated Exa results (deterministic, derived from query); not fetched from network.
    # This server persists the request/response into operations per business rules.
    if limit is None:
        limit = 10

    total_available = 1000
    end = min(start_offset + limit, total_available)

    qnorm = re.sub(r"\s+", " ", query.strip())
    qslug = re.sub(r"[^a-zA-Z0-9]+", "-", qnorm).strip("-").lower() or "query"
    results = []
    for i in range(start_offset, end):
        h = hashlib.sha256((qnorm + "|" + str(i)).encode("utf-8")).hexdigest()
        url = f"https://example.com/{qslug}/{i}?r={h[:10]}"
        results.append({
            "id": "exa_" + h[:24],
            "url": url,
            "title": f"{qnorm} — result {i+1}",
            "snippet": f"Result {i+1} for '{qnorm}'.",
            "score": round(1.0 / (1 + (i - start_offset)), 6)
        })

    has_more = end < total_available
    next_cursor = None
    if has_more:
        payload = {"q": query, "o": end}
        enc = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    result_obj = {"results": results, "has_more": has_more, "next_cursor": next_cursor, "total_available": total_available}

    op = _oplog(ws["id"], key["id"], "exa_web_search", "completed",
                req_obj, result_obj=result_obj, error_obj=None, cost_units=1,
                started_at=started_at, finished_at=finished_at)

    # update key last_used_at
    for k in api_keys:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = finished_at
            k["updated_at"] = finished_at
            break
    _save("api_keys.json", api_keys)

    return {
        "operation_id": op["id"],
        "workspace_id": ws["id"],
        "query": query,
        "results": results,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "usage": {"month_used": used + 1, "month_limit": lim},
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def websets_manager(action, workspace_id, webset_id=None, body=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0380000" if __import__("os").path.isdir("./environment_mix/0380000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    websets = _load("websets.json")
    webset_items = _load("webset_items.json")
    operations = _load("operations.json")

    def _month_key(dt_iso_z):
        try:
            d = datetime.datetime.fromisoformat(dt_iso_z.replace("Z", "+00:00"))
        except Exception:
            d = datetime.datetime.utcnow()
        return (d.year, d.month)

    def _sum_cost(workspace_id_, typ, year, month):
        s = 0
        for op in operations:
            if op.get("workspace_id") != workspace_id_:
                continue
            if op.get("type") != typ:
                continue
            ca = op.get("created_at") or op.get("started_at") or op.get("updated_at")
            if not isinstance(ca, str):
                continue
            try:
                d = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00"))
            except Exception:
                continue
            if d.year == year and d.month == month:
                cu = op.get("cost_units")
                if isinstance(cu, int) and cu >= 0:
                    s += cu
        return s

    def _gen_id(prefix):
        return prefix + "_01H" + hashlib.sha1((now + "|" + prefix + "|" + str(time.time_ns())).encode("utf-8")).hexdigest().upper()[:18]

    def _oplog(workspace_id_, api_key_id_, typ, status, request_obj, result_obj=None, error_obj=None, cost_units=0, started_at=None, finished_at=None, webset_id_=None):
        op_id = "op_" + hashlib.sha256((now + "|" + typ + "|" + (workspace_id_ or "") + "|" + str(len(operations)+1)).encode("utf-8")).hexdigest()[:24]
        row = {
            "id": op_id,
            "workspace_id": workspace_id_,
            "api_key_id": api_key_id_,
            "type": typ,
            "webset_id": webset_id_,
            "status": status,
            "request": request_obj if request_obj is not None else {},
            "result": result_obj,
            "error": error_obj,
            "cost_units": int(cost_units) if isinstance(cost_units, int) and cost_units >= 0 else 0,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(row)
        _save("operations.json", operations)
        return row

    def _validate_ws_id(ws_id):
        return isinstance(ws_id, str) and re.match(r"^ws_01H[A-Z0-9]{15,}$", ws_id or "") is not None

    def _validate_wset_id(x):
        return isinstance(x, str) and re.match(r"^wset_01H[A-Z0-9]{15,}$", x or "") is not None

    def _validate_wsi_id(x):
        return isinstance(x, str) and re.match(r"^wsi_01H[A-Z0-9]{15,}$", x or "") is not None

    def _canonical_url(u):
        if not isinstance(u, str) or not u.strip():
            return None
        u = u.strip()
        try:
            p = urlparse(u)
        except Exception:
            return None
        if p.scheme not in ("http", "https") or not p.netloc:
            return None
        # normalize: lowercase scheme/host, strip fragment
        norm = p._replace(scheme=p.scheme.lower(), netloc=p.netloc.lower(), fragment="").geturl()
        return norm

    # Basic validation
    allowed_actions = {"create_webset", "ingest_items", "search_webset", "run_enhancement", "setup_notification", "check_notification"}
    if action not in allowed_actions:
        # attribute to workspace if possible; else return validation error
        ws_attr = next((w for w in workspaces if w.get("id") == workspace_id), None) if isinstance(workspace_id, str) else None
        op = _oplog(ws_attr["id"] if ws_attr else (workspace_id if isinstance(workspace_id, str) else "ws_unknown"),
                    None, "webset_search", "failed",
                    {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                    error_obj={"code": "VALIDATION_ERROR", "message": "Invalid action"},
                    cost_units=0, started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "Invalid action", operation_id=op["id"])

    if not _validate_ws_id(workspace_id):
        op = _oplog(workspace_id if isinstance(workspace_id, str) else "ws_unknown",
                    None, "webset_search", "failed",
                    {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                    error_obj={"code": "VALIDATION_ERROR", "message": "workspace_id is invalid"},
                    cost_units=0, started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "workspace_id is invalid", operation_id=op["id"])

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None:
        op = _oplog(workspace_id, None, "webset_search", "failed",
                    {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                    error_obj={"code": "NOT_FOUND", "message": "Workspace not found"},
                    cost_units=0, started_at=now, finished_at=now)
        return _err("NOT_FOUND", "Workspace not found", operation_id=op["id"])

    # Ambient auth: choose an active key for this workspace if present; else proceed with api_key_id null (server config)
    key = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)

    # Workspace status gating for mutating operations
    mutating_actions = {"create_webset", "run_enhancement", "setup_notification"}
    # ingest_items is a mutation too per schema; treat as mutation for workspace active requirement as well.
    mutating_actions.add("ingest_items")
    if action in mutating_actions and ws.get("status") != "active":
        op_type = {"create_webset": "webset_create", "ingest_items": "webset_create", "run_enhancement": "enhancement_run",
                   "setup_notification": "notification_setup"}.get(action, "webset_create")
        op = _oplog(workspace_id, key["id"] if key else None, op_type, "failed",
                    {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                    error_obj={"code": "INVALID_TRANSITION", "message": "Workspace is not active"},
                    cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id if _validate_wset_id(webset_id) else None)
        return _err("INVALID_TRANSITION", "Workspace is not active", operation_id=op["id"], workspace_status=ws.get("status"))

    if body is None:
        body = {}
    if not isinstance(body, dict):
        op = _oplog(workspace_id, key["id"] if key else None, "webset_search", "failed",
                    {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                    error_obj={"code": "VALIDATION_ERROR", "message": "body must be an object"},
                    cost_units=0, started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "body must be an object")

    # Helpers for reads: webset must exist and not be deleted for operations (except explicit deleted status transitions via update not provided here)
    def _get_webset_or_err(wset_id, for_read=False):
        if not _validate_wset_id(wset_id):
            return None, _err("VALIDATION_ERROR", "webset_id is invalid")
        wset = next((x for x in websets if x.get("id") == wset_id and x.get("workspace_id") == workspace_id), None)
        if wset is None:
            return None, _err("NOT_FOUND", "Webset not found")
        if wset.get("status") == "deleted":
            # soft-hidden from reads and operations
            return None, _err("NOT_FOUND", "Webset not found")
        return wset, None

    # ACTION: create_webset
    if action == "create_webset":
        webset_obj = body.get("webset")
        if not isinstance(webset_obj, dict):
            op = _oplog(workspace_id, key["id"] if key else None, "webset_create", "failed",
                        {"action": action, "workspace_id": workspace_id, "body": body},
                        error_obj={"code": "VALIDATION_ERROR", "message": "body.webset is required"},
                        cost_units=0, started_at=now, finished_at=now)
            return _err("VALIDATION_ERROR", "body.webset is required", operation_id=op["id"])
        name = webset_obj.get("name")
        if not isinstance(name, str) or not name.strip():
            op = _oplog(workspace_id, key["id"] if key else None, "webset_create", "failed",
                        {"action": action, "workspace_id": workspace_id, "body": body},
                        error_obj={"code": "VALIDATION_ERROR", "message": "webset.name is required"},
                        cost_units=0, started_at=now, finished_at=now)
            return _err("VALIDATION_ERROR", "webset.name is required", operation_id=op["id"])

        # unique(workspace_id, name) among non-deleted
        for existing in websets:
            if existing.get("workspace_id") == workspace_id and existing.get("name") == name and existing.get("status") != "deleted":
                op = _oplog(workspace_id, key["id"] if key else None, "webset_create", "failed",
                            {"action": action, "workspace_id": workspace_id, "body": body},
                            error_obj={"code": "CONFLICT", "message": "A webset with this name already exists"},
                            cost_units=0, started_at=now, finished_at=now)
                return _err("CONFLICT", "A webset with this name already exists", operation_id=op["id"])

        status = webset_obj.get("status") or "draft"
        if status not in ("draft", "active", "archived", "deleted"):
            op = _oplog(workspace_id, key["id"] if key else None, "webset_create", "failed",
                        {"action": action, "workspace_id": workspace_id, "body": body},
                        error_obj={"code": "VALIDATION_ERROR", "message": "Invalid webset.status"},
                        cost_units=0, started_at=now, finished_at=now)
            return _err("VALIDATION_ERROR", "Invalid webset.status", operation_id=op["id"])

        wset_id = _gen_id("wset")
        row = {
            "id": wset_id,
            "workspace_id": workspace_id,
            "name": name,
            "description": webset_obj.get("description") if isinstance(webset_obj.get("description"), str) else None,
            "source_config": webset_obj.get("source_config") if isinstance(webset_obj.get("source_config"), dict) else None,
            "status": status,
            "item_count": 0,
            "created_at": now,
            "updated_at": now
        }
        websets.append(row)
        _save("websets.json", websets)

        op = _oplog(workspace_id, key["id"] if key else None, "webset_create", "completed",
                    {"action": action, "workspace_id": workspace_id, "body": body},
                    result_obj={"webset_id": wset_id},
                    cost_units=0, started_at=now, finished_at=now, webset_id_=wset_id)

        return {"operation_id": op["id"], "webset": row, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

    # ACTIONS that require webset_id
    if action in ("ingest_items", "search_webset", "run_enhancement", "setup_notification", "check_notification"):
        wset, err = _get_webset_or_err(webset_id)
        if err:
            op_type = {
                "ingest_items": "webset_create",
                "search_webset": "webset_search",
                "run_enhancement": "enhancement_run",
                "setup_notification": "notification_setup",
                "check_notification": "notification_check",
            }[action]
            op = _oplog(workspace_id, key["id"] if key else None, op_type, "failed",
                        {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                        error_obj={"code": err["error"]["code"], "message": err["error"]["message"]},
                        cost_units=0, started_at=now, finished_at=now,
                        webset_id_=webset_id if _validate_wset_id(webset_id) else None)
            return err | {"operation_id": op["id"]} if isinstance(err, dict) else err

    # ACTION: ingest_items (upsert on unique(webset_id,url))
    if action == "ingest_items":
        items = body.get("items")
        if not isinstance(items, list) or len(items) == 0:
            op = _oplog(workspace_id, key["id"] if key else None, "webset_create", "failed",
                        {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                        error_obj={"code": "VALIDATION_ERROR", "message": "body.items must be a non-empty array"},
                        cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
            return _err("VALIDATION_ERROR", "body.items must be a non-empty array", operation_id=op["id"])

        added = 0
        updated = 0
        touched_ids = []
        for it in items:
            if not isinstance(it, dict):
                continue
            url = _canonical_url(it.get("url"))
            source = it.get("source")
            if url is None or source not in ("exa_search", "manual", "import", "notification"):
                continue
            status = it.get("status") or "active"
            if status not in ("active", "removed"):
                continue

            existing = next((x for x in webset_items if x.get("webset_id") == webset_id and x.get("url") == url), None)
            if existing is None:
                wsi_id = _gen_id("wsi")
                row = {
                    "id": wsi_id,
                    "webset_id": webset_id,
                    "url": url,
                    "title": it.get("title") if isinstance(it.get("title"), str) else None,
                    "excerpt": it.get("excerpt") if isinstance(it.get("excerpt"), str) else None,
                    "content_text": it.get("content_text") if isinstance(it.get("content_text"), str) else None,
                    "source": source,
                    "exa_result_id": it.get("exa_result_id") if isinstance(it.get("exa_result_id"), str) else None,
                    "published_at": it.get("published_at") if isinstance(it.get("published_at"), str) else None,
                    "status": status,
                    "enhancements": None,
                    "enhanced_at": None,
                    "created_at": now,
                    "updated_at": now,
                }
                webset_items.append(row)
                added += 1
                touched_ids.append(wsi_id)
            else:
                # upsert: update provided fields, keep created_at
                existing["title"] = it.get("title") if isinstance(it.get("title"), str) else existing.get("title")
                existing["excerpt"] = it.get("excerpt") if isinstance(it.get("excerpt"), str) else existing.get("excerpt")
                existing["content_text"] = it.get("content_text") if isinstance(it.get("content_text"), str) else existing.get("content_text")
                existing["source"] = source
                existing["exa_result_id"] = it.get("exa_result_id") if isinstance(it.get("exa_result_id"), str) else existing.get("exa_result_id")
                existing["published_at"] = it.get("published_at") if isinstance(it.get("published_at"), str) else existing.get("published_at")
                # lifecycle transition enforcement for item status
                prev = existing.get("status")
                if prev == "active" and status == "removed":
                    existing["status"] = "removed"
                elif prev == "removed" and status == "active":
                    existing["status"] = "active"
                elif prev == status:
                    pass
                else:
                    # invalid status or transition: skip
                    pass
                existing["updated_at"] = now
                updated += 1
                touched_ids.append(existing["id"])

        if added == 0 and updated == 0:
            op = _oplog(workspace_id, key["id"] if key else None, "webset_create", "failed",
                        {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                        error_obj={"code": "VALIDATION_ERROR", "message": "No valid items to ingest"},
                        cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
            return _err("VALIDATION_ERROR", "No valid items to ingest", operation_id=op["id"])

        # update webset item_count (active items only)
        active_count = 0
        for x in webset_items:
            if x.get("webset_id") == webset_id and x.get("status") == "active":
                active_count += 1
        for wsrow in websets:
            if wsrow.get("id") == webset_id:
                wsrow["item_count"] = active_count
                wsrow["updated_at"] = now
                break

        _save("webset_items.json", webset_items)
        _save("websets.json", websets)

        op = _oplog(workspace_id, key["id"] if key else None, "webset_create", "completed",
                    {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                    result_obj={"added": added, "updated": updated, "touched_item_ids": touched_ids, "item_count": active_count},
                    cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)

        return {
            "operation_id": op["id"],
            "webset_id": webset_id,
            "added": added,
            "updated": updated,
            "touched_item_ids": touched_ids,
            "item_count": active_count,
            "meta": {"latency_ms": int((time.time() - t0) * 1000)}
        }

    # ACTION: search_webset
    if action == "search_webset":
        search = body.get("search")
        if not isinstance(search, dict):
            op = _oplog(workspace_id, key["id"] if key else None, "webset_search", "failed",
                        {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                        error_obj={"code": "VALIDATION_ERROR", "message": "body.search is required"},
                        cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
            return _err("VALIDATION_ERROR", "body.search is required", operation_id=op["id"])

        q = search.get("query")
        if not isinstance(q, str) or not q.strip():
            op = _oplog(workspace_id, key["id"] if key else None, "webset_search", "failed",
                        {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                        error_obj={"code": "VALIDATION_ERROR", "message": "search.query is required"},
                        cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
            return _err("VALIDATION_ERROR", "search.query is required", operation_id=op["id"])

        lim = search.get("limit", 10)
        if lim is None:
            lim = 10
        if not isinstance(lim, int) or lim <= 0:
            op = _oplog(workspace_id, key["id"] if key else None, "webset_search", "failed",
                        {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                        error_obj={"code": "VALIDATION_ERROR", "message": "search.limit must be a positive integer"},
                        cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
            return _err("VALIDATION_ERROR", "search.limit must be a positive integer", operation_id=op["id"])

        sort = search.get("sort", "relevance")
        if sort not in ("relevance", "published_at_desc", "published_at_asc", "created_at_desc", "created_at_asc"):
            op = _oplog(workspace_id, key["id"] if key else None, "webset_search", "failed",
                        {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                        error_obj={"code": "VALIDATION_ERROR", "message": "search.sort is invalid"},
                        cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
            return _err("VALIDATION_ERROR", "search.sort is invalid", operation_id=op["id"])

        start_offset = 0
        cur = search.get("cursor")
        if cur is not None:
            if not isinstance(cur, str) or not cur.strip():
                op = _oplog(workspace_id, key["id"] if key else None, "webset_search", "failed",
                            {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                            error_obj={"code": "VALIDATION_ERROR", "message": "search.cursor is malformed"},
                            cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
                return _err("VALIDATION_ERROR", "search.cursor is malformed", operation_id=op["id"])
            try:
                raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
                payload = json.loads(raw.decode("utf-8"))
                if not isinstance(payload, dict) or payload.get("w") != webset_id or payload.get("q") != q or "o" not in payload:
                    raise ValueError("bad cursor")
                if not isinstance(payload["o"], int) or payload["o"] < 0:
                    raise ValueError("bad offset")
                start_offset = payload["o"]
            except Exception:
                op = _oplog(workspace_id, key["id"] if key else None, "webset_search", "failed",
                            {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                            error_obj={"code": "VALIDATION_ERROR", "message": "search.cursor is malformed"},
                            cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
                return _err("VALIDATION_ERROR", "search.cursor is malformed", operation_id=op["id"])

        include_removed = bool(search.get("include_removed")) if "include_removed" in search else False

        # Search match: simple substring over url/title/excerpt/content_text (if present)
        qn = q.strip().lower()
        candidates = []
        for it in webset_items:
            if it.get("webset_id") != webset_id:
                continue
            if not include_removed and it.get("status") == "removed":
                continue
            hay = " ".join([str(it.get("url") or ""), str(it.get("title") or ""), str(it.get("excerpt") or ""), str(it.get("content_text") or "")]).lower()
            if qn in hay:
                candidates.append(it)

        def _parse_dt(s):
            if not isinstance(s, str): return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        if sort == "relevance":
            # crude relevance: count occurrences
            def score(it):
                hay = " ".join([str(it.get("url") or ""), str(it.get("title") or ""), str(it.get("excerpt") or ""), str(it.get("content_text") or "")]).lower()
                return hay.count(qn)
            candidates.sort(key=lambda it: (score(it), _parse_dt(it.get("published_at")) or datetime.datetime.min, _parse_dt(it.get("created_at")) or datetime.datetime.min), reverse=True)
        elif sort == "published_at_desc":
            candidates.sort(key=lambda it: (_parse_dt(it.get("published_at")) or datetime.datetime.min, _parse_dt(it.get("created_at")) or datetime.datetime.min), reverse=True)
        elif sort == "published_at_asc":
            candidates.sort(key=lambda it: (_parse_dt(it.get("published_at")) or datetime.datetime.max, _parse_dt(it.get("created_at")) or datetime.datetime.max))
        elif sort == "created_at_desc":
            candidates.sort(key=lambda it: (_parse_dt(it.get("created_at")) or datetime.datetime.min), reverse=True)
        elif sort == "created_at_asc":
            candidates.sort(key=lambda it: (_parse_dt(it.get("created_at")) or datetime.datetime.max))

        total = len(candidates)
        page = candidates[start_offset:start_offset + lim]
        end = start_offset + len(page)
        has_more = end < total
        next_cursor = None
        if has_more:
            payload = {"w": webset_id, "q": q, "o": end, "s": sort, "r": include_removed}
            next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

        op = _oplog(workspace_id, key["id"] if key else None, "webset_search", "completed",
                    {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body, "include_removed": include_removed},
                    result_obj={"total": total, "returned": len(page), "next_cursor": next_cursor},
                    cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)

        return {
            "operation_id": op["id"],
            "webset_id": webset_id,
            "items": page,
            "total": total,
            "limit": lim,
            "cursor": cur,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "meta": {"latency_ms": int((time.time() - t0) * 1000)}
        }

    # ACTION: run_enhancement (quota: monthly_enhancement_limit; cost_units = number of items enhanced)
    if action == "run_enhancement":
        enh = body.get("enhancement")
        if not isinstance(enh, dict):
            op = _oplog(workspace_id, key["id"] if key else None, "enhancement_run", "failed",
                        {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                        error_obj={"code": "VALIDATION_ERROR", "message": "body.enhancement is required"},
                        cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
            return _err("VALIDATION_ERROR", "body.enhancement is required", operation_id=op["id"])

        item_ids = enh.get("item_ids")
        query = enh.get("query")
        target_items = []

        if item_ids is not None:
            if not isinstance(item_ids, list) or any((not _validate_wsi_id(x)) for x in item_ids):
                op = _oplog(workspace_id, key["id"] if key else None, "enhancement_run", "failed",
                            {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                            error_obj={"code": "VALIDATION_ERROR", "message": "enhancement.item_ids must be an array of item ids"},
                            cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
                return _err("VALIDATION_ERROR", "enhancement.item_ids must be an array of item ids", operation_id=op["id"])
            idset = set(item_ids)
            for it in webset_items:
                if it.get("webset_id") == webset_id and it.get("id") in idset:
                    if it.get("status") == "active":
                        target_items.append(it)
        elif isinstance(query, str) and query.strip():
            qn = query.strip().lower()
            for it in webset_items:
                if it.get("webset_id") != webset_id:
                    continue
                if it.get("status") != "active":
                    continue
                hay = " ".join([str(it.get("url") or ""), str(it.get("title") or ""), str(it.get("excerpt") or ""), str(it.get("content_text") or "")]).lower()
                if qn in hay:
                    target_items.append(it)
        else:
            op = _oplog(workspace_id, key["id"] if key else None, "enhancement_run", "failed",
                        {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                        error_obj={"code": "VALIDATION_ERROR", "message": "Provide enhancement.item_ids or enhancement.query"},
                        cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
            return _err("VALIDATION_ERROR", "Provide enhancement.item_ids or enhancement.query", operation_id=op["id"])

        if len(target_items) == 0:
            op = _oplog(workspace_id, key["id"] if key else None, "enhancement_run", "failed",
                        {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                        error_obj={"code": "NOT_FOUND", "message": "No matching active items to enhance"},
                        cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
            return _err("NOT_FOUND", "No matching active items to enhance", operation_id=op["id"])

        year, month = _month_key(now)
        used = _sum_cost(workspace_id, "enhancement_run", year, month)
        lim = ws.get("monthly_enhancement_limit")
        if not isinstance(lim, int) or lim < 0:
            lim = 0
        cost = len(target_items)
        if used + cost > lim:
            op = _oplog(workspace_id, key["id"] if key else None, "enhancement_run", "failed",
                        {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                        error_obj={"code": "QUOTA_EXCEEDED", "message": "Monthly enhancement quota exceeded", "used": used, "limit": lim, "attempted": cost},
                        cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
            return _err("QUOTA_EXCEEDED", "Monthly enhancement quota exceeded", used=used, limit=lim, attempted=cost, operation_id=op["id"])

        started_at = now
        op = _oplog(workspace_id, key["id"] if key else None, "enhancement_run", "running",
                    {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                    result_obj=None, error_obj=None, cost_units=0, started_at=started_at, finished_at=None, webset_id_=webset_id)

        # Apply deterministic "enhancement" outputs
        enhanced_ids = []
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        for it in target_items:
            url = str(it.get("url") or "")
            title = str(it.get("title") or "")
            txt = (title + " " + (str(it.get("excerpt") or "")))[:500]
            digest = hashlib.sha256((url + "|" + txt).encode("utf-8")).hexdigest()
            enh_out = {
                "summary_v1": {"summary": (txt.strip()[:160] or f"Summary for {url}")},
                "entities_v1": {"entities": list({w.strip(".,;:()[]{}").lower() for w in re.findall(r"[A-Za-z]{4,}", txt)})[:10]},
                "hash_v1": {"sha256": digest},
            }
            if not isinstance(it.get("enhancements"), dict):
                it["enhancements"] = {}
            it["enhancements"].update(enh_out)
            it["enhanced_at"] = finished
            it["updated_at"] = finished
            enhanced_ids.append(it.get("id"))

        _save("webset_items.json", webset_items)

        # Transition op running -> completed
        for op_row in operations:
            if op_row.get("id") == op["id"]:
                op_row["status"] = "completed"
                op_row["result"] = {"enhanced_item_ids": enhanced_ids, "count": len(enhanced_ids)}
                op_row["cost_units"] = cost
                op_row["finished_at"] = finished
                op_row["updated_at"] = finished
                break
        _save("operations.json", operations)

        return {
            "operation_id": op["id"],
            "webset_id": webset_id,
            "enhanced_item_ids": enhanced_ids,
            "count": len(enhanced_ids),
            "usage": {"month_used": used + cost, "month_limit": lim},
            "meta": {"latency_ms": int((time.time() - t0) * 1000)}
        }

    # ACTION: setup_notification / check_notification (stored in operations.result; minimal)
    if action in ("setup_notification", "check_notification"):
        notif = body.get("notification")
        if action == "setup_notification":
            if not isinstance(notif, dict) or not isinstance(notif.get("query"), str) or not notif.get("query").strip():
                op = _oplog(workspace_id, key["id"] if key else None, "notification_setup", "failed",
                            {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                            error_obj={"code": "VALIDATION_ERROR", "message": "notification.query is required"},
                            cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
                return _err("VALIDATION_ERROR", "notification.query is required", operation_id=op["id"])
            op = _oplog(workspace_id, key["id"] if key else None, "notification_setup", "completed",
                        {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                        result_obj={"enabled": True, "query": notif["query"], "webset_id": webset_id},
                        cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
            return {"operation_id": op["id"], "notification": op["result"], "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

        # check_notification: find most recent setup for this webset and echo status
        last = None
        for op_row in reversed(operations):
            if op_row.get("workspace_id") == workspace_id and op_row.get("webset_id") == webset_id and op_row.get("type") == "notification_setup" and op_row.get("status") == "completed":
                last = op_row
                break
        res = {"enabled": False, "webset_id": webset_id}
        if last and isinstance(last.get("result"), dict):
            res = {"enabled": True, "webset_id": webset_id, "query": last["result"].get("query"), "last_setup_operation_id": last.get("id")}

        op = _oplog(workspace_id, key["id"] if key else None, "notification_check", "completed",
                    {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                    result_obj=res, cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id)
        return {"operation_id": op["id"], "notification": res, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

    # Should not reach
    op = _oplog(workspace_id, key["id"] if key else None, "webset_search", "failed",
                {"action": action, "workspace_id": workspace_id, "webset_id": webset_id, "body": body},
                error_obj={"code": "VALIDATION_ERROR", "message": "Unsupported action"},
                cost_units=0, started_at=now, finished_at=now, webset_id_=webset_id if _validate_wset_id(webset_id) else None)
    return _err("VALIDATION_ERROR", "Unsupported action", operation_id=op["id"])

def websets_guide(topic, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0380000" if __import__("os").path.isdir("./environment_mix/0380000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    supported = {"overview", "create_webset", "ingest_items", "search_webset", "enhance_items", "notifications", "best_practices"}
    if topic not in supported:
        return _err("VALIDATION_ERROR", "topic must be one of: " + ", ".join(sorted(supported)))

    # Read-only tool: must not mutate any collections
    # It may read aggregated metadata
    workspaces = _load("workspaces.json")
    websets = _load("websets.json")
    items = _load("webset_items.json")
    operations = _load("operations.json")

    active_ws = sum(1 for w in workspaces if w.get("status") == "active")
    visible_websets = sum(1 for w in websets if w.get("status") != "deleted")
    active_items = sum(1 for it in items if it.get("status") == "active")

    recent_ops = []
    for op in reversed(operations[-50:]):
        recent_ops.append({k: op.get(k) for k in ("id", "type", "status", "workspace_id", "webset_id", "created_at")})

    guides = {
        "overview": {
            "title": "Websets overview",
            "content": [
                "A webset is a workspace-owned collection of web documents (items).",
                "Common flow: create a webset → ingest items (from Exa search, manual URLs, imports, notifications) → search within the webset → run enhancements → optionally configure notifications."
            ],
        },
        "create_webset": {
            "title": "Create a webset",
            "content": [
                "Use websets_manager with action='create_webset' and body.webset.name.",
                "Optional: description, source_config, and initial status (draft/active/archived).",
                "Webset names must be unique within a workspace (excluding deleted)."
            ],
            "example": {
                "action": "create_webset",
                "workspace_id": "ws_...",
                "body": {"webset": {"name": "My Webset", "description": "Track relevant pages", "status": "draft"}}
            }
        },
        "ingest_items": {
            "title": "Ingest items",
            "content": [
                "Use websets_manager action='ingest_items' with a webset_id and body.items[].",
                "Items are upserted by (webset_id, url).",
                "Removed items are excluded from search results unless explicitly included."
            ],
            "example": {
                "action": "ingest_items",
                "workspace_id": "ws_...",
                "webset_id": "wset_...",
                "body": {"items": [{"url": "https://example.com/a", "source": "manual", "title": "Example"}]}
            }
        },
        "search_webset": {
            "title": "Search within a webset",
            "content": [
                "Use websets_manager action='search_webset' with body.search.query.",
                "Pagination is cursor-based; supply the next_cursor from a previous response to fetch the next page.",
                "Sorting options include relevance and timestamp-based sorts."
            ],
            "example": {
                "action": "search_webset",
                "workspace_id": "ws_...",
                "webset_id": "wset_...",
                "body": {"search": {"query": "acquisition", "limit": 10, "sort": "relevance"}}
            }
        },
        "enhance_items": {
            "title": "Enhance items",
            "content": [
                "Use websets_manager action='run_enhancement' with body.enhancement.item_ids or body.enhancement.query.",
                "Enhancement outputs are stored on each webset item in enhancements and enhanced_at.",
                "Enhancement quota is enforced monthly per workspace."
            ],
            "example": {
                "action": "run_enhancement",
                "workspace_id": "ws_...",
                "webset_id": "wset_...",
                "body": {"enhancement": {"query": "pricing"}}
            }
        },
        "notifications": {
            "title": "Notifications",
            "content": [
                "Use websets_manager action='setup_notification' with body.notification.query to configure detection of new matching content.",
                "Use action='check_notification' to retrieve current notification status for a webset."
            ],
            "example": {
                "action": "setup_notification",
                "workspace_id": "ws_...",
                "webset_id": "wset_...",
                "body": {"notification": {"query": "site:example.com product launch"}}
            }
        },
        "best_practices": {
            "title": "Best practices",
            "content": [
                "Start with a draft webset and iterate on source_config and ingestion before switching to active.",
                "Deduplicate by canonical URLs; prefer https and stable canonical links.",
                "Run enhancements on smaller batches to manage quota and improve throughput.",
                "Use search to validate your collection and remove noisy items (status='removed')."
            ]
        }
    }

    return {
        "topic": topic,
        "guide": guides.get(topic),
        "service_stats": {
            "active_workspaces": active_ws,
            "visible_websets": visible_websets,
            "active_items": active_items,
            "recent_operations": recent_ops[:10],
        },
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def auth_whoami(api_key=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0380000" if __import__("os").path.isdir("./environment_mix/0380000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    operations = _load("operations.json")

    def _month_key(dt_iso_z):
        try:
            d = datetime.datetime.fromisoformat(dt_iso_z.replace("Z", "+00:00"))
        except Exception:
            d = datetime.datetime.utcnow()
        return (d.year, d.month)

    def _sum_cost(workspace_id, typ, year, month):
        s = 0
        for op in operations:
            if op.get("workspace_id") != workspace_id:
                continue
            if op.get("type") != typ:
                continue
            ca = op.get("created_at") or op.get("started_at") or op.get("updated_at")
            if not isinstance(ca, str):
                continue
            try:
                d = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00"))
            except Exception:
                continue
            if d.year == year and d.month == month:
                cu = op.get("cost_units")
                if isinstance(cu, int) and cu >= 0:
                    s += cu
        return s

    def _oplog(workspace_id, api_key_id, status, request_obj, result_obj=None, error_obj=None):
        op_id = "op_" + hashlib.sha256((now + "|whoami|" + (workspace_id or "") + "|" + str(len(operations)+1)).encode("utf-8")).hexdigest()[:24]
        row = {
            "id": op_id,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "type": "webset_search",
            "webset_id": None,
            "status": status,
            "request": request_obj if request_obj is not None else {},
            "result": result_obj,
            "error": error_obj,
            "cost_units": 0,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(row)
        _save("operations.json", operations)
        return row

    # Authenticate explicit credential if provided: match against id or client-visible value.
    # Store only has key_hash (hashed secret) and id; no plaintext exists, so only id is usable here.
    key_row = None
    if api_key is not None:
        if not isinstance(api_key, str) or not api_key.strip():
            return _err("UNAUTHORIZED", "API key is missing/invalid")
        candidate = api_key.strip()
        key_row = next((k for k in api_keys if k.get("id") == candidate), None)
        if key_row is None:
            # cannot validate a plaintext secret because not stored
            return _err("UNAUTHORIZED", "API key is missing/invalid")
    else:
        # If no key provided, use any active key as server-default
        key_row = next((k for k in api_keys if k.get("status") == "active"), None)
        if key_row is None:
            return _err("UNAUTHORIZED", "API key is missing/invalid")

    if key_row.get("status") != "active":
        ws_id = key_row.get("workspace_id") if isinstance(key_row.get("workspace_id"), str) else "ws_unknown"
        op = _oplog(ws_id, key_row.get("id"), "failed",
                    {"api_key": api_key},
                    error_obj={"code": "UNAUTHORIZED", "message": "API key is revoked"})
        return _err("UNAUTHORIZED", "API key is revoked", operation_id=op["id"])

    ws = next((w for w in workspaces if w.get("id") == key_row.get("workspace_id")), None)
    if ws is None:
        op = _oplog(key_row.get("workspace_id") or "ws_unknown", key_row.get("id"), "failed",
                    {"api_key": api_key},
                    error_obj={"code": "FORBIDDEN", "message": "Key is not entitled to this workspace"})
        return _err("FORBIDDEN", "Key is not entitled to this workspace", operation_id=op["id"])

    year, month = _month_key(now)
    used_search = _sum_cost(ws["id"], "exa_web_search", year, month)
    used_enh = _sum_cost(ws["id"], "enhancement_run", year, month)

    lim_search = ws.get("monthly_search_limit")
    if not isinstance(lim_search, int) or lim_search < 0:
        lim_search = 0
    lim_enh = ws.get("monthly_enhancement_limit")
    if not isinstance(lim_enh, int) or lim_enh < 0:
        lim_enh = 0

    result = {
        "caller": {
            "api_key_id": key_row.get("id"),
            "api_key_name": key_row.get("name"),
            "api_key_status": key_row.get("status"),
        },
        "workspace": {
            "id": ws.get("id"),
            "name": ws.get("name"),
            "plan": ws.get("plan"),
            "status": ws.get("status"),
        },
        "scopes": ["websets:read", "websets:write", "search:exa", "enhancements:run", "notifications:manage"],
        "quota": {
            "month": f"{year:04d}-{month:02d}",
            "search": {"used": used_search, "limit": lim_search, "remaining": max(0, lim_search - used_search)},
            "enhancement": {"used": used_enh, "limit": lim_enh, "remaining": max(0, lim_enh - used_enh)},
        }
    }

    # Record operation (read) and update last_used_at for successful auth
    op = _oplog(ws["id"], key_row.get("id"), "completed", {"api_key": api_key}, result_obj={"whoami": True}, error_obj=None)

    for k in api_keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    result["operation_id"] = op["id"]
    result["meta"] = {"latency_ms": int((time.time() - t0) * 1000)}
    return result

def workspaces_list(api_key=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0380000" if __import__("os").path.isdir("./environment_mix/0380000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- helpers ---
    def _b64e(s):
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("ascii").rstrip("=")
    def _b64d(s):
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii")).decode("utf-8")

    def _make_op_id(ts):
        # ws_01H... style is for workspace ids; operations have no specified pattern. Use op_ + timestamp + counter.
        return "op_" + ts.replace("-", "").replace(":", "").replace("Z", "") + "_" + str(int(time.time() * 1000))

    def _month_prefix(dt_iso_z):
        # dt_iso_z like 2026-08-04T12:34:56Z
        if not isinstance(dt_iso_z, str) or len(dt_iso_z) < 7:
            return None
        return dt_iso_z[:7]  # YYYY-MM

    def _record_operation(ops, workspace_id, api_key_id, op_type, req, status_val, result=None, error=None, cost_units=0):
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op = {
            "id": _make_op_id(ts),
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "type": op_type,
            "webset_id": None,
            "status": status_val,
            "request": req if isinstance(req, dict) else {"raw": req},
            "result": result,
            "error": error,
            "cost_units": int(cost_units) if isinstance(cost_units, int) and cost_units >= 0 else 0,
            "started_at": ts,
            "finished_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(op)
        return op

    def _find_auth_context(provided_key):
        """
        Returns dict: {workspace, api_key_row_or_none}
        Ambient auth: If provided_key is None, choose any active workspace and an active api key if available.
        If provided_key is provided, match by api_keys.id OR api_keys.key_hash (client-visible in this datastore).
        """
        workspaces = _load("workspaces.json")
        keys = _load("api_keys.json")

        def ws_ok(ws):
            return isinstance(ws, dict) and ws.get("id") and ws.get("status") in ("active", "suspended", "deleted")

        if provided_key is not None:
            if not isinstance(provided_key, str) or not provided_key.strip():
                return None
            k = provided_key.strip()
            key_row = None
            for r in keys:
                if not isinstance(r, dict):
                    continue
                if r.get("id") == k or r.get("key_hash") == k:
                    key_row = r
                    break
            if not key_row or key_row.get("status") != "active":
                return None
            ws = next((w for w in workspaces if ws_ok(w) and w.get("id") == key_row.get("workspace_id")), None)
            if not ws:
                return None
            return {"workspace": ws, "api_key": key_row}

        # Ambient: pick a workable combination. Prefer active key in an active workspace; otherwise any workspace.
        for w in workspaces:
            if not ws_ok(w):
                continue
            # try to attach an active key if exists
            krow = next((r for r in keys if isinstance(r, dict) and r.get("workspace_id") == w.get("id") and r.get("status") == "active"), None)
            return {"workspace": w, "api_key": krow}
        return None

    # --- validate inputs ---
    if status is not None and status not in ("active", "suspended", "deleted"):
        # schema enum
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    ops = _load("operations.json")

    # --- auth ---
    ctx = _find_auth_context(api_key)
    if not ctx:
        # record a failed op with no attributable workspace is disallowed by business rule,
        # but we can only comply if we can attribute. If no workspace exists, return UNAUTHORIZED without op.
        # If at least one workspace exists, attribute to one and record.
        any_ws = next((w for w in _load("workspaces.json") if isinstance(w, dict) and w.get("id")), None)
        if any_ws:
            _record_operation(
                ops, any_ws.get("id"), None, "webset_search",
                {"endpoint": "workspaces_list", "status": status, "limit": limit, "cursor": cursor},
                "failed",
                result=None,
                error={"code": "UNAUTHORIZED", "message": "Missing or invalid API key."},
                cost_units=0
            )
            _save("operations.json", ops)
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    # Permission model in this local store is workspace-scoped; listing "visible workspaces" means only the authed workspace.
    authed_ws = ctx["workspace"]
    authed_key = ctx["api_key"]
    api_key_id = authed_key.get("id") if isinstance(authed_key, dict) else None

    # --- fetch and paginate ---
    all_ws = [authed_ws]  # only the workspace visible to its own key
    if status is not None:
        all_ws = [w for w in all_ws if w.get("status") == status]

    # sort by created_at then id for stable ordering
    def _sort_key(w):
        return (w.get("created_at") or "", w.get("id") or "")
    all_ws.sort(key=_sort_key)

    start = 0
    if cursor:
        try:
            dec = _b64d(cursor)
            m = re.match(r"^i:(\d+)$", dec)
            if not m:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            start = int(m.group(1))
            if start < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = all_ws[start:start + limit]
    next_cursor = None
    if start + limit < len(all_ws):
        next_cursor = _b64e(f"i:{start + limit}")
    has_more = next_cursor is not None

    # record operation (read)
    op = _record_operation(
        ops,
        authed_ws.get("id"),
        api_key_id,
        "webset_search",
        {"endpoint": "workspaces_list", "status": status, "limit": limit, "cursor": cursor},
        "completed",
        result={"returned": len(page), "total": len(all_ws), "has_more": has_more},
        error=None,
        cost_units=0
    )
    # latency (store inside result for observability)
    latency_ms = int((time.time() - t0) * 1000)
    op["result"]["latency_ms"] = latency_ms
    op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("operations.json", ops)

    return {
        "object": "list",
        "data": page,
        "total": len(all_ws),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def workspaces_update(workspace_id, workspace, api_key=None, **_extra):
    import json, os, datetime, uuid, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0380000" if __import__("os").path.isdir("./environment_mix/0380000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_s = now.isoformat() + "Z"

    # ---------- input validation ----------
    if not isinstance(workspace_id, str) or not workspace_id:
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string.", field="workspace_id")
    if not re.match(r"^ws_01H[A-Z0-9]{15,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is not in the expected format.", field="workspace_id")

    if not isinstance(workspace, dict):
        return _err("VALIDATION_ERROR", "workspace must be an object.", field="workspace")

    allowed_fields = {"name", "plan", "monthly_search_limit", "monthly_enhancement_limit", "status"}
    for k in workspace.keys():
        if k not in allowed_fields:
            return _err("VALIDATION_ERROR", "workspace contains unknown field.", field=f"workspace.{k}")

    if api_key is not None and (not isinstance(api_key, str) or not api_key.strip()):
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string when provided.", field="api_key")

    if "name" in workspace and (not isinstance(workspace["name"], str) or not workspace["name"].strip()):
        return _err("VALIDATION_ERROR", "workspace.name must be a non-empty string.", field="workspace.name")

    tool_plan_enum = {"free", "pro", "team", "enterprise"}
    if "plan" in workspace:
        if not isinstance(workspace["plan"], str) or workspace["plan"] not in tool_plan_enum:
            return _err("VALIDATION_ERROR", "workspace.plan must be one of: free, pro, team, enterprise.", field="workspace.plan")

    for fld in ("monthly_search_limit", "monthly_enhancement_limit"):
        if fld in workspace:
            v = workspace[fld]
            if not isinstance(v, int) or isinstance(v, bool) or v < 0:
                return _err("VALIDATION_ERROR", f"workspace.{fld} must be an integer >= 0.", field=f"workspace.{fld}")

    if "status" in workspace:
        if not isinstance(workspace["status"], str) or workspace["status"] not in {"active", "suspended", "deleted"}:
            return _err("VALIDATION_ERROR", "workspace.status must be one of: active, suspended, deleted.", field="workspace.status")

    # ---------- load collections ----------
    ws_rows = _load("workspaces.json")
    keys_rows = _load("api_keys.json")
    ops_rows = _load("operations.json")

    if not isinstance(ws_rows, list): ws_rows = []
    if not isinstance(keys_rows, list): keys_rows = []
    if not isinstance(ops_rows, list): ops_rows = []

    # ---------- helpers ----------
    def _new_op_id():
        # keep vendor-ish prefix; uniqueness matters most
        return "op_" + uuid.uuid4().hex

    def _find_ws(ws_id):
        for r in ws_rows:
            if isinstance(r, dict) and r.get("id") == ws_id:
                return r
        return None

    def _ws_name_taken(name, exclude_id):
        for r in ws_rows:
            if not isinstance(r, dict):
                continue
            if r.get("id") != exclude_id and r.get("name") == name:
                return True
        return False

    def _resolve_auth_workspace_and_key(api_key_param, target_ws_id):
        """
        Ambient auth behavior:
        - If api_key provided: authenticate by matching api_keys.id (client-visible) OR key_hash (also client-visible per store),
          prefer active keys. Attribute to that workspace. If target differs, allow only if there exists an active key
          for target workspace (server/admin capability), and then attribute to target workspace for the mutation.
        - If api_key absent: choose the target workspace if it exists; otherwise any workspace with at least one active key.
        Return (attributed_workspace_row, used_key_row_or_none, error_or_none).
        """
        # candidate list of (ws_row, key_row_or_none)
        target_ws = _find_ws(target_ws_id)

        def _active_key_for_ws(ws_id):
            for k in keys_rows:
                if not isinstance(k, dict):
                    continue
                if k.get("workspace_id") == ws_id and k.get("status") == "active":
                    return k
            return None

        if api_key_param is not None:
            token = api_key_param.strip()
            matched_keys = []
            for k in keys_rows:
                if not isinstance(k, dict):
                    continue
                if k.get("id") == token or k.get("key_hash") == token:
                    matched_keys.append(k)
            # prefer active
            key_row = None
            for k in matched_keys:
                if k.get("status") == "active":
                    key_row = k
                    break
            if key_row is None and matched_keys:
                key_row = matched_keys[0]

            if key_row is None:
                return (None, None, _err("UNAUTHORIZED", "Invalid API key."))

            key_ws = _find_ws(key_row.get("workspace_id"))
            if key_ws is None:
                return (None, None, _err("UNAUTHORIZED", "API key is not associated with a valid workspace.", api_key_id=key_row.get("id")))

            # If targeting another workspace, only allow if target has an active key (admin/server context)
            if target_ws is not None and target_ws.get("id") != key_ws.get("id"):
                if _active_key_for_ws(target_ws.get("id")) is None:
                    return (None, None, _err("UNAUTHORIZED", "API key is not authorized for the requested workspace.", api_key_id=key_row.get("id"), workspace_id=target_ws.get("id")))
                # attribute to target workspace (admin acting on target)
                return (target_ws, key_row, None)

            # normal: attribute to key's workspace (or to target if same id)
            return (key_ws if target_ws is None else target_ws, key_row, None)

        # Ambient: prefer target if exists; otherwise any ws that can plausibly be administered (has an active key)
        if target_ws is not None:
            return (target_ws, None, None)

        for w in ws_rows:
            if not isinstance(w, dict):
                continue
            if _active_key_for_ws(w.get("id")) is not None:
                return (w, None, None)

        # last resort: any workspace at all
        for w in ws_rows:
            if isinstance(w, dict) and w.get("id"):
                return (w, None, None)

        return (None, None, _err("UNAUTHORIZED", "No workspace context is available."))

    def _record_operation(workspace_row, key_row, status, request_payload, result_payload=None, error_payload=None, cost_units=0, webset_id=None):
        op = {
            "id": _new_op_id(),
            "workspace_id": workspace_row.get("id") if isinstance(workspace_row, dict) else None,
            "api_key_id": key_row.get("id") if isinstance(key_row, dict) else None,
            "type": "webset_create",  # closest existing category for a workspace mutation; schema has no workspace_update
            "webset_id": webset_id,
            "status": status,
            "request": request_payload if isinstance(request_payload, dict) else {},
            "result": result_payload,
            "error": error_payload,
            "cost_units": int(cost_units) if isinstance(cost_units, int) and not isinstance(cost_units, bool) and cost_units >= 0 else 0,
            "started_at": now_s,
            "finished_at": now_s,
            "created_at": now_s,
            "updated_at": now_s,
        }
        ops_rows.append(op)
        _save("operations.json", ops_rows)
        return op

    # ---------- resolve context ----------
    authed_ws, used_key, auth_err = _resolve_auth_workspace_and_key(api_key, workspace_id)
    if auth_err:
        # record attempt only if we could attribute workspace (we couldn't)
        return auth_err

    target_ws = _find_ws(workspace_id)
    if target_ws is None:
        # no mutation effect
        _record_operation(
            authed_ws,
            used_key,
            "failed",
            request_payload={"workspace_id": workspace_id, "workspace": workspace, "action": "workspaces_update"},
            error_payload={"code": "NOT_FOUND", "message": "Workspace not found.", "workspace_id": workspace_id},
            cost_units=0,
        )
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # privilege check: must be same workspace as attributed context unless admin/server ability already validated in resolver
    if authed_ws.get("id") != target_ws.get("id"):
        _record_operation(
            authed_ws,
            used_key,
            "failed",
            request_payload={"workspace_id": workspace_id, "workspace": workspace, "action": "workspaces_update"},
            error_payload={"code": "UNAUTHORIZED", "message": "Operation not permitted for this workspace.", "workspace_id": workspace_id},
            cost_units=0,
        )
        return _err("UNAUTHORIZED", "Not authorized for this workspace.", workspace_id=workspace_id)

    # ---------- enforce constraints & lifecycle transitions ----------
    # Schema constraints: unique(name), limits >= 0 handled already, transitions enforced if status changes.
    if "name" in workspace:
        new_name = workspace["name"].strip()
        if _ws_name_taken(new_name, exclude_id=workspace_id):
            _record_operation(
                authed_ws,
                used_key,
                "failed",
                request_payload={"workspace_id": workspace_id, "workspace": workspace, "action": "workspaces_update"},
                error_payload={"code": "CONFLICT", "message": "Workspace name must be unique.", "field": "name"},
                cost_units=0,
            )
            return _err("CONFLICT", "Workspace name must be unique.", field="workspace.name")

    # transitions
    current_status = target_ws.get("status")
    new_status = workspace.get("status", current_status)

    transitions = {
        "active": {"suspended", "deleted"},
        "suspended": {"active", "deleted"},
        "deleted": set(),
    }
    if "status" in workspace and new_status != current_status:
        if current_status not in transitions or new_status not in transitions[current_status]:
            _record_operation(
                authed_ws,
                used_key,
                "failed",
                request_payload={"workspace_id": workspace_id, "workspace": workspace, "action": "workspaces_update"},
                error_payload={"code": "INVALID_TRANSITION", "message": "Illegal workspace status transition.", "from": current_status, "to": new_status},
                cost_units=0,
            )
            return _err("INVALID_TRANSITION", "Illegal workspace status transition.", from_status=current_status, to_status=new_status)

    # IMPORTANT: Do NOT block updates when suspended/deleted; that rule applies to other mutating operations, not workspace_update.
    # Apply updates
    changed = False
    for fld in ("name", "monthly_search_limit", "monthly_enhancement_limit", "status"):
        if fld in workspace:
            val = workspace[fld]
            if fld == "name":
                val = val.strip()
            if target_ws.get(fld) != val:
                target_ws[fld] = val
                changed = True

    # plan: tool enum includes "team" but DB enum doesn't; map "team" -> "pro" for storage compatibility
    if "plan" in workspace:
        plan_val = workspace["plan"]
        if plan_val == "team":
            plan_val = "pro"
        if plan_val not in {"free", "pro", "enterprise"}:
            _record_operation(
                authed_ws,
                used_key,
                "failed",
                request_payload={"workspace_id": workspace_id, "workspace": workspace, "action": "workspaces_update"},
                error_payload={"code": "VALIDATION_ERROR", "message": "Unsupported plan for this server datastore.", "plan": workspace["plan"]},
                cost_units=0,
            )
            return _err("VALIDATION_ERROR", "Unsupported plan value for this server.", field="workspace.plan", allowed=["free", "pro", "enterprise"], provided=workspace["plan"])
        if target_ws.get("plan") != plan_val:
            target_ws["plan"] = plan_val
            changed = True

    if not changed:
        # No success without effect: treat as conflict-free idempotency? Here it's an update call; return conflict? Prefer success only if effect.
        _record_operation(
            authed_ws,
            used_key,
            "failed",
            request_payload={"workspace_id": workspace_id, "workspace": workspace, "action": "workspaces_update"},
            error_payload={"code": "CONFLICT", "message": "No changes to apply."},
            cost_units=0,
        )
        return _err("CONFLICT", "No changes to apply.")

    target_ws["updated_at"] = now_s
    _save("workspaces.json", ws_rows)

    # if api key provided and matched active, update last_used_at
    if isinstance(used_key, dict) and used_key.get("status") == "active":
        used_key["last_used_at"] = now_s
        used_key["updated_at"] = now_s
        _save("api_keys.json", keys_rows)

    op = _record_operation(
        authed_ws,
        used_key,
        "completed",
        request_payload={"workspace_id": workspace_id, "workspace": workspace, "action": "workspaces_update"},
        result_payload={"workspace": target_ws},
        cost_units=0,
    )

    return {
        "workspace": target_ws,
        "operation_id": op.get("id"),
        "latency_ms": int((time.time() - t0) * 1000),
    }

def api_keys_create(workspace_id, name, api_key=None, **_extra):
    import json, os, datetime, time, secrets, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0380000" if __import__("os").path.isdir("./environment_mix/0380000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _make_op_id(ts):
        return "op_" + ts.replace("-", "").replace(":", "").replace("Z", "") + "_" + str(int(time.time() * 1000))

    def _record_operation(ops, ws_id, api_key_id, op_type, req, status_val, result=None, error=None, cost_units=0):
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op = {
            "id": _make_op_id(ts),
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "type": op_type,
            "webset_id": None,
            "status": status_val,
            "request": req if isinstance(req, dict) else {"raw": req},
            "result": result,
            "error": error,
            "cost_units": int(cost_units) if isinstance(cost_units, int) and cost_units >= 0 else 0,
            "started_at": ts,
            "finished_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(op)
        return op

    def _find_auth_context(provided_key):
        workspaces = _load("workspaces.json")
        keys = _load("api_keys.json")

        def ws_ok(ws):
            return isinstance(ws, dict) and ws.get("id") and ws.get("status") in ("active", "suspended", "deleted")

        if provided_key is not None:
            if not isinstance(provided_key, str) or not provided_key.strip():
                return None
            k = provided_key.strip()
            key_row = None
            for r in keys:
                if not isinstance(r, dict):
                    continue
                if r.get("id") == k or r.get("key_hash") == k:
                    key_row = r
                    break
            if not key_row or key_row.get("status") != "active":
                return None
            ws = next((w for w in workspaces if ws_ok(w) and w.get("id") == key_row.get("workspace_id")), None)
            if not ws:
                return None
            return {"workspace": ws, "api_key": key_row}

        for w in workspaces:
            if not ws_ok(w):
                continue
            krow = next((r for r in keys if isinstance(r, dict) and r.get("workspace_id") == w.get("id") and r.get("status") == "active"), None)
            return {"workspace": w, "api_key": krow}
        return None

    # validate
    if not isinstance(workspace_id, str) or not re.match(r"^ws_01H[A-Z0-9]{15,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    name = name.strip()

    workspaces = _load("workspaces.json")
    keys = _load("api_keys.json")
    ops = _load("operations.json")

    # auth
    ctx = _find_auth_context(api_key)
    if not ctx:
        any_ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id")), None)
        if any_ws:
            _record_operation(
                ops, any_ws.get("id"), None, "notification_setup",
                {"endpoint": "api_keys_create", "workspace_id": workspace_id, "name": name},
                "failed",
                error={"code": "UNAUTHORIZED", "message": "Missing or invalid API key."},
                cost_units=0
            )
            _save("operations.json", ops)
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    authed_ws = ctx["workspace"]
    authed_key = ctx["api_key"]
    api_key_id = authed_key.get("id") if isinstance(authed_key, dict) else None

    # permission: only manage keys in own workspace
    if authed_ws.get("id") != workspace_id:
        _record_operation(
            ops, authed_ws.get("id"), api_key_id, "notification_setup",
            {"endpoint": "api_keys_create", "workspace_id": workspace_id, "name": name},
            "failed",
            error={"code": "UNAUTHORIZED", "message": "Not authorized to manage keys for this workspace."},
            cost_units=0
        )
        _save("operations.json", ops)
        return _err("UNAUTHORIZED", "Not authorized to manage keys for this workspace.")

    # workspace must exist and be active
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _record_operation(
            ops, authed_ws.get("id"), api_key_id, "notification_setup",
            {"endpoint": "api_keys_create", "workspace_id": workspace_id, "name": name},
            "failed",
            error={"code": "NOT_FOUND", "message": "Workspace not found."},
            cost_units=0
        )
        _save("operations.json", ops)
        return _err("NOT_FOUND", "Workspace not found.")

    if ws.get("status") != "active":
        _record_operation(
            ops, workspace_id, api_key_id, "notification_setup",
            {"endpoint": "api_keys_create", "workspace_id": workspace_id, "name": name},
            "failed",
            error={"code": "UNAUTHORIZED", "message": "Workspace is not active."},
            cost_units=0
        )
        _save("operations.json", ops)
        return _err("UNAUTHORIZED", "Workspace is not active.")

    # enforce unique(workspace_id, name)
    if any(isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("name") == name for k in keys):
        _record_operation(
            ops, workspace_id, api_key_id, "notification_setup",
            {"endpoint": "api_keys_create", "workspace_id": workspace_id, "name": name},
            "failed",
            error={"code": "CONFLICT", "message": "API key name already exists in this workspace."},
            cost_units=0
        )
        _save("operations.json", ops)
        return _err("CONFLICT", "API key name already exists in this workspace.")

    # generate secret and store hash in key_hash (but datastore uses key_hash as "client-visible value" for auth too)
    secret = "exa_ws_" + secrets.token_urlsafe(24)
    key_hash = hashlib.sha256(secret.encode("utf-8")).hexdigest()

    # enforce unique(key_hash)
    if any(isinstance(k, dict) and k.get("key_hash") == key_hash for k in keys):
        # extremely unlikely; regenerate once
        secret = "exa_ws_" + secrets.token_urlsafe(24)
        key_hash = hashlib.sha256(secret.encode("utf-8")).hexdigest()
        if any(isinstance(k, dict) and k.get("key_hash") == key_hash for k in keys):
            _record_operation(
                ops, workspace_id, api_key_id, "notification_setup",
                {"endpoint": "api_keys_create", "workspace_id": workspace_id, "name": name},
                "failed",
                error={"code": "CONFLICT", "message": "Could not generate unique API key."},
                cost_units=0
            )
            _save("operations.json", ops)
            return _err("CONFLICT", "Could not generate unique API key.")

    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    new_id = "key_" + ts.replace("-", "").replace(":", "").replace("Z", "") + "_" + str(int(time.time() * 1000))
    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "name": name,
        "key_hash": key_hash,
        "status": "active",
        "last_used_at": None,
        "created_at": ts,
        "updated_at": ts,
    }
    keys.append(row)
    _save("api_keys.json", keys)

    op = _record_operation(
        ops, workspace_id, api_key_id, "notification_setup",
        {"endpoint": "api_keys_create", "workspace_id": workspace_id, "name": name},
        "completed",
        result={"api_key_id": new_id},
        error=None,
        cost_units=0
    )
    op["result"]["latency_ms"] = int((time.time() - t0) * 1000)
    op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("operations.json", ops)

    # never return secret again; but create returns it once
    returned = dict(row)
    returned.pop("key_hash", None)
    return {"api_key": returned, "secret": secret}

def api_keys_list(workspace_id, api_key=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0380000" if __import__("os").path.isdir("./environment_mix/0380000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^ws_01H[A-Z0-9]{15,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id")

    if api_key is not None and (not isinstance(api_key, str) or not api_key.strip()):
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string when provided.", field="api_key")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "revoked"):
            return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")

    if limit is None:
        limit = 25
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")

    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")

    # ---- Load datastore ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    ops = _load("operations.json")

    # ---- Resolve auth context ----
    # Authenticate only by api_keys.id (client-visible). Never by key_hash.
    used_key_row = None
    if api_key is not None:
        k = api_key.strip()
        for r in api_keys:
            if isinstance(r, dict) and r.get("id") == k:
                used_key_row = r
                break
        if used_key_row is None or used_key_row.get("status") != "active":
            # Record attempt if we can attribute to some workspace (best-effort: target workspace if exists)
            ws_exists = any(isinstance(ws, dict) and ws.get("id") == workspace_id for ws in workspaces)
            if ws_exists:
                ops.append({
                    "id": "op_" + __import__("uuid").uuid4().hex,
                    "workspace_id": workspace_id,
                    "api_key_id": used_key_row.get("id") if isinstance(used_key_row, dict) else None,
                    "type": "webset_search",
                    "webset_id": None,
                    "status": "failed",
                    "request": {"action": "api_keys_list", "workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor},
                    "result": None,
                    "error": {"code": "UNAUTHORIZED", "message": "Invalid or revoked api_key."},
                    "cost_units": 0,
                    "started_at": now,
                    "finished_at": now,
                    "created_at": now,
                    "updated_at": now,
                })
                _save("operations.json", ops)
            return _err("UNAUTHORIZED", "Invalid or revoked api_key.")
        used_ws_id = used_key_row.get("workspace_id")
    else:
        # Ambient auth: choose a usable workspace context that matches the request
        used_ws_id = workspace_id
        # pick any active key for attribution if available
        for kr in api_keys:
            if isinstance(kr, dict) and kr.get("workspace_id") == used_ws_id and kr.get("status") == "active":
                used_key_row = kr
                break

    # Must be in same workspace
    if used_ws_id != workspace_id:
        ops.append({
            "id": "op_" + __import__("uuid").uuid4().hex,
            "workspace_id": used_ws_id,
            "api_key_id": used_key_row.get("id") if isinstance(used_key_row, dict) else None,
            "type": "webset_search",
            "webset_id": None,
            "status": "failed",
            "request": {"action": "api_keys_list", "workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor},
            "result": None,
            "error": {"code": "UNAUTHORIZED", "message": "Credential is not authorized for the specified workspace."},
            "cost_units": 0,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("operations.json", ops)
        return _err("UNAUTHORIZED", "Credential is not authorized for the specified workspace.")

    # workspace must exist (read: empty is ok for keys, but workspace itself should exist)
    ws_row = None
    for ws in workspaces:
        if isinstance(ws, dict) and ws.get("id") == workspace_id:
            ws_row = ws
            break
    if ws_row is None:
        ops.append({
            "id": "op_" + __import__("uuid").uuid4().hex,
            "workspace_id": workspace_id,
            "api_key_id": used_key_row.get("id") if isinstance(used_key_row, dict) else None,
            "type": "webset_search",
            "webset_id": None,
            "status": "failed",
            "request": {"action": "api_keys_list", "workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor},
            "result": None,
            "error": {"code": "NOT_FOUND", "message": "Workspace not found."},
            "cost_units": 0,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("operations.json", ops)
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # ---- Filter, sort, paginate ----
    rows = []
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    # stable sort by created_at then id
    def _k(x):
        return (x.get("created_at") or "", x.get("id") or "")
    rows.sort(key=_k)

    start = 0
    if cursor is not None:
        # cursor is last-seen id (opaque-ish). If not found, start at 0.
        for i, r in enumerate(rows):
            if r.get("id") == cursor:
                start = i + 1
                break

    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < len(rows)
    if has_more and page:
        next_cursor = page[-1].get("id")

    # Strip secret material (never return key_hash)
    def _public_key(r):
        return {
            "id": r.get("id"),
            "workspace_id": r.get("workspace_id"),
            "name": r.get("name"),
            "status": r.get("status"),
            "last_used_at": r.get("last_used_at"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        }
    public_page = [_public_key(r) for r in page]

    # record operation (read)
    ops.append({
        "id": "op_" + __import__("uuid").uuid4().hex,
        "workspace_id": workspace_id,
        "api_key_id": used_key_row.get("id") if isinstance(used_key_row, dict) else None,
        "type": "webset_search",
        "webset_id": None,
        "status": "completed",
        "request": {"action": "api_keys_list", "workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor},
        "result": {"returned": len(public_page), "total": len(rows), "has_more": has_more, "next_cursor": next_cursor},
        "error": None,
        "cost_units": 0,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now,
    })
    _save("operations.json", ops)

    # update last_used_at for the authenticating key (if any)
    if isinstance(used_key_row, dict):
        used_key_row["last_used_at"] = now
        used_key_row["updated_at"] = now
        _save("api_keys.json", api_keys)

    return {
        "data": public_page,
        "page": {"limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more, "total": len(rows)},
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def operations_get(operation_id, api_key=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0380000" if __import__("os").path.isdir("./environment_mix/0380000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_s = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate: accept any non-empty string (do not enforce pattern too strictly; vendor param schema is patterned,
    # but audit indicates callers may pass other ids and should get a data response when possible).
    if not isinstance(operation_id, str) or not operation_id.strip():
        return _err("VALIDATION_ERROR", "operation_id must be a non-empty string.", field="operation_id")
    operation_id = operation_id.strip()
    if api_key is not None and (not isinstance(api_key, str) or not api_key.strip()):
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string when provided.", field="api_key")

    ops_rows = _load("operations.json")
    keys_rows = _load("api_keys.json")
    ws_rows = _load("workspaces.json")
    if not isinstance(ops_rows, list): ops_rows = []
    if not isinstance(keys_rows, list): keys_rows = []
    if not isinstance(ws_rows, list): ws_rows = []

    def _find_ws(ws_id):
        for w in ws_rows:
            if isinstance(w, dict) and w.get("id") == ws_id:
                return w
        return None

    def _resolve_context(api_key_param):
        """
        Return (workspace_row_or_none, key_row_or_none, error_or_none)
        Reads are allowed for any workspace; however, if api_key is provided, use it to scope access.
        Authenticate against api_keys.id OR api_keys.key_hash (both are client-visible in this datastore).
        """
        if api_key_param is not None:
            token = api_key_param.strip()
            matched = None
            for k in keys_rows:
                if not isinstance(k, dict):
                    continue
                if k.get("id") == token or k.get("key_hash") == token:
                    matched = k
                    break
            if matched is None:
                return (None, None, _err("UNAUTHORIZED", "Invalid API key."))
            ws = _find_ws(matched.get("workspace_id"))
            if ws is None:
                return (None, None, _err("UNAUTHORIZED", "API key is not associated with a valid workspace.", api_key_id=matched.get("id")))
            return (ws, matched, None)

        # Ambient: choose a workspace that actually has operations (so reads can succeed), else any workspace.
        ws_by_id = {}
        for w in ws_rows:
            if isinstance(w, dict) and w.get("id"):
                ws_by_id[w["id"]] = w
        for op in ops_rows:
            if isinstance(op, dict):
                wsid = op.get("workspace_id")
                if wsid in ws_by_id:
                    return (ws_by_id[wsid], None, None)
        for w in ws_rows:
            if isinstance(w, dict) and w.get("id"):
                return (w, None, None)
        return (None, None, _err("UNAUTHORIZED", "No workspace context is available."))

    ctx_ws, ctx_key, auth_err = _resolve_context(api_key)
    if auth_err:
        return auth_err

    # Find operation by id
    op_row = None
    for op in ops_rows:
        if isinstance(op, dict) and op.get("id") == operation_id:
            op_row = op
            break

    # Always record the access attempt if we can attribute to a workspace
    def _append_access_op(status, result=None, error=None):
        if not isinstance(ctx_ws, dict) or not ctx_ws.get("id"):
            return None
        # Use notification_check as closest read-like operation type available.
        access = {
            "id": "op_" + __import__("uuid").uuid4().hex,
            "workspace_id": ctx_ws.get("id"),
            "api_key_id": ctx_key.get("id") if isinstance(ctx_key, dict) else None,
            "type": "notification_check",
            "webset_id": None,
            "status": status,
            "request": {"operation_id": operation_id, "action": "operations_get"},
            "result": result,
            "error": error,
            "cost_units": 0,
            "started_at": now_s,
            "finished_at": now_s,
            "created_at": now_s,
            "updated_at": now_s,
        }
        ops_rows.append(access)
        _save("operations.json", ops_rows)
        return access

    if op_row is None:
        _append_access_op("failed", error={"code": "NOT_FOUND", "message": "Operation not found.", "operation_id": operation_id})
        return _err("NOT_FOUND", "Operation not found.", operation_id=operation_id)

    # Authorization: if api_key provided, operation must belong to that workspace; if ambient, allow (service context).
    if api_key is not None and isinstance(ctx_ws, dict):
        if op_row.get("workspace_id") != ctx_ws.get("id"):
            _append_access_op("failed", error={"code": "UNAUTHORIZED", "message": "Operation is not in caller's workspace.", "operation_id": operation_id})
            return _err("UNAUTHORIZED", "Operation is not in the caller's workspace.", operation_id=operation_id)

    # update last_used_at on successful keyed auth
    if isinstance(ctx_key, dict) and ctx_key.get("status") == "active":
        ctx_key["last_used_at"] = now_s
        ctx_key["updated_at"] = now_s
        _save("api_keys.json", keys_rows)

    _append_access_op("completed", result={"fetched_operation_id": operation_id})

    return {
        "operation": op_row,
        "latency_ms": int((time.time() - t0) * 1000),
    }
